# Let's check available packages and run our backtracking search
import sys
print("Python version:", sys.version)

# Run the backtracking search without any external imports
class GracefulLabelingSearch:
    def __init__(self):
        self.n = 15
        self.m = 27
        # Precompute edges
        self.edges = []
        self.adj = [[] for _ in range(15)]

        # Within cliques
        for g in range(5):
            base = g * 3
            for i in range(3):
                for j in range(i+1, 3):
                    u, v = base + i, base + j
                    eidx = len(self.edges)
                    self.edges.append((u, v))
                    self.adj[u].append((eidx, v))
                    self.adj[v].append((eidx, u))

        # Between cliques
        for g in range(4):
            for i in range(3):
                u, v = g*3 + i, (g+1)*3 + i
                eidx = len(self.edges)
                self.edges.append((u, v))
                self.adj[u].append((eidx, v))
                self.adj[v].append((eidx, u))

        self.solution = None

    def search(self):
        self.assignments = [None] * 15
        self.used_labels = set()
        self.used_diffs = set()
        return self._dfs(0)

    def _dfs(self, assigned_count):
        if assigned_count == 15:
            self.solution = list(self.assignments)
            return True

        # Find most constrained unassigned vertex
        best_v = -1
        best_score = -1
        for v in range(15):
            if self.assignments[v] is not None:
                continue
            score = sum(1 for eidx, nb in self.adj[v] if self.assignments[nb] is not None)
            if score > best_score:
                best_score = score
                best_v = v

        v = best_v

        # Try all unused labels
        candidates = []
        for label in range(28):
            if label in self.used_labels:
                continue

            ok = True
            new_diffs = []
            for eidx, nb in self.adj[v]:
                if self.assignments[nb] is not None:
                    d = abs(label - self.assignments[nb])
                    if d == 0 or d in self.used_diffs:
                        ok = False
                        break
                    new_diffs.append(d)

            if not ok:
                continue

            # Forward checking
            fc_ok = True
            for eidx, nb in self.adj[v]:
                if self.assignments[nb] is None:
                    has_valid = False
                    for nb_label in range(28):
                        if nb_label in self.used_labels or nb_label == label:
                            continue
                        d_nb = abs(label - nb_label)
                        if d_nb != 0 and d_nb not in self.used_diffs:
                            nb_ok = True
                            for eidx2, nb2 in self.adj[nb]:
                                if nb2 != v and self.assignments[nb2] is not None:
                                    d2 = abs(nb_label - self.assignments[nb2])
                                    if d2 == 0 or d2 in self.used_diffs or d2 == d_nb:
                                        nb_ok = False
                                        break
                            if nb_ok:
                                has_valid = True
                                break
                    if not has_valid:
                        fc_ok = False
                        break

            if fc_ok:
                candidates.append((label, new_diffs))

        for label, new_diffs in candidates:
            self.assignments[v] = label
            self.used_labels.add(label)
            for d in new_diffs:
                self.used_diffs.add(d)

            if self._dfs(assigned_count + 1):
                return True

            self.assignments[v] = None
            self.used_labels.remove(label)
            for d in new_diffs:
                self.used_diffs.remove(d)

        return False

search = GracefulLabelingSearch()
print("Starting search...")
import time
start = time.time()
found = search.search()
print(f"Found: {found}, time: {time.time() - start:.2f}s")
if found:
    print("Solution:", search.solution)

    # Verify
    diffs = []
    for u, v in search.edges:
        d = abs(search.solution[u] - search.solution[v])
        diffs.append(d)
    print("Sorted diffs:", sorted(diffs))
    print("All 1-27?", sorted(diffs) == list(range(1, 28)))

